/* Lists, prompt setup, and saved runs follow the stock scorer workflow. */
(() => {
 const el=id=>document.getElementById(id), escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 document.querySelector('.top-tabs').insertAdjacentHTML('beforeend','<button type="button" data-top-tab="scorer" aria-selected="false">AI scoring</button>');
 const panel=document.createElement('section'); panel.id='scorer-panel';panel.dataset.topPanel='scorer';panel.hidden=true;
 panel.innerHTML=`<div class="heading"><div><p class="eyebrow">PROMPT-BASED RANKINGS</p><h1>Movie scorer</h1><p class="muted">Build a movie list, describe what matters, and save a ranked run.</p></div></div>
 <nav class="saved-views" aria-label="Scoring sections"><button data-score-page="setup">Set run</button><button data-score-page="lists">Movie lists</button><button data-score-page="runs">Runs</button><button data-score-page="starred">Starred runs</button></nav>
 <p id="ai-status" role="status"></p>
 <section data-score-section="setup"><form id="ai-run-form" class="ai-card">
 <h2>Set run</h2><div class="ai-grid"><label>Run name<input id="ai-name" maxlength="120" required placeholder="Weekend thrillers"></label><label>Movie list<select id="ai-list" required></select></label></div>
 <label>Scoring prompt<textarea id="ai-prompt" rows="6" maxlength="20000" required placeholder="Score how well MOVIE fits an atmospheric, suspenseful movie night with clever twists and little gore."></textarea></label>
 <p class="muted">Use the uppercase keyword MOVIE for the title and year, e.g. Inception (2010). {{IMDB_ID}} is also available; {{YEAR}} remains supported for existing prompts. Each request also includes the movie’s IMDb metadata. Scores are 0–100 with an explanation. The model has no live web search.</p>
 <div class="ai-grid"><label>Movies to score<input id="ai-count" type="number" min="1" max="10000" value="1" required></label><label>Response token limit<input id="ai-tokens" type="number" min="100" max="16000" value="2000" required></label><label>Concurrent requests<input id="ai-workers" type="number" min="1" max="20" value="4" required></label></div>
 <p class="muted">Model: DeepSeek V4 Flash · deepseek/deepseek-v4-flash-0731 · reasoning disabled</p>
 <div class="ai-actions"><button type="submit">Preview run</button><button type="button" id="ai-save-prompt">Save prompt draft</button></div>
 <div id="ai-preview" hidden></div></form></section>
 <section data-score-section="lists" hidden><div class="ai-card"><h2>Movie lists</h2><div class="ai-grid"><label>Saved list<select id="ai-edit-list"><option value="">New list</option></select></label><label>List name<input id="ai-list-name" maxlength="120" placeholder="Movies to score"></label></div>
 <div class="ai-actions"><button id="ai-new-list">New list</button><button id="ai-save-list">Save list</button><button id="ai-copy-list">Save as copy</button><button id="ai-archive-list">Archive list</button><button id="ai-add-library">Add current library page</button></div>
 <p class="muted">Add current library page uses the movies currently displayed in Movies, including its filters and selected All / Starred / Seen view. Saved lists and runs stay on this computer.</p>
 <div class="ai-grid"><div><label>Find movies<input id="ai-search" type="search" placeholder="Title or IMDb ID"></label><div id="ai-candidates" class="table-scroll"></div><div class="ai-actions"><button id="ai-search-prev">Previous</button><span id="ai-search-page"></span><button id="ai-search-next">Next</button><button id="ai-add-page">Add search page</button></div></div>
 <div><h3>Selected movies <span id="ai-selected-count">0</span></h3><div id="ai-selected" class="table-scroll"></div><div class="ai-actions"><button id="ai-selected-prev">Previous</button><span id="ai-selected-page"></span><button id="ai-selected-next">Next</button></div></div></div></div></section>
 <section data-score-section="runs" hidden><div class="ai-card"><h2 id="ai-history-title">Runs</h2><div id="ai-history" class="table-scroll"></div></div></section>
 <section data-score-section="detail" hidden><div class="ai-card"><h2 id="ai-run-title"></h2><p id="ai-run-prompt" class="ai-pre"></p><div id="ai-run-actions" class="ai-actions"></div><div id="ai-metrics" class="ai-metrics"></div>
 <p class="muted">Stop finishes requests already in flight. Resume processes queued movies; Retry failed requeues failed responses. Completed scores are preserved. Workers continue when you close the tab or restart the web server.</p>
 <div class="ai-actions"><label>Results<select id="ai-result-view"><option value="done">Ranking</option><option value="failed">Failed</option><option value="pending">Queued / scoring</option><option value="all">All movies</option></select></label><label>Search ranking<input id="ai-result-search" type="search" placeholder="Movie title"></label><label>Sort<select id="ai-result-sort"><option value="score">Score: high to low</option><option value="title">Title: A–Z</option><option value="year">Year: newest first</option></select></label><button id="ai-export">Export CSV</button></div>
 <div id="ai-results" class="table-scroll"></div><div class="ai-actions"><button id="ai-result-prev">Previous</button><span id="ai-result-page"></span><button id="ai-result-next">Next</button></div>
 <details><summary>Provider usage</summary><div id="ai-providers" class="table-scroll"></div></details></div></section>`;
 document.querySelector('main').append(panel);
 let lists=[], selected=new Map(), editing=null, candidates=[], searchPage=1, searchPages=1, selectedPage=1, resultPage=1, currentRun=null, page='setup', preview=null, searchVersion=0;
 const status=message=>{el('ai-status').textContent=message;};
 const api=async(path,payload)=>{const r=await fetch('/api/scorer/'+path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;};
 const task=fn=>async event=>{const b=event?.currentTarget; if(b?.tagName==='BUTTON')b.disabled=true;try{await fn(event);}catch(e){status(e.message);}finally{if(b?.tagName==='BUTTON')b.disabled=false;}};
 function show(next){page=next;try{localStorage.setItem('frame-ai-view',JSON.stringify({page:next,run:currentRun?.id}));}catch{}document.querySelectorAll('[data-score-section]').forEach(s=>s.hidden=s.dataset.scoreSection!==(next==='starred'?'runs':next));document.querySelectorAll('[data-score-page]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scorePage===next)));if(next==='runs'||next==='starred')loadHistory().catch(e=>status(e.message));if(next==='lists'&&!candidates.length)findMovies().catch(e=>status(e.message));}
 document.querySelectorAll('[data-score-page]').forEach(b=>b.onclick=()=>show(b.dataset.scorePage));
 function table(headers,rows){return `<table><thead><tr>${headers.map(h=>`<th class="action-heading">${escape(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}">No movies yet.</td></tr>`}</tbody></table>`;}
 const movieCells=m=>`<td>${escape(m.primaryTitle)}</td><td>${escape(m.startYear??'—')}</td><td>${escape(m.averageRating??'—')}</td>`;
 function renderSelection(){const values=[...selected.values()];selectedPage=Math.max(1,Math.min(selectedPage,Math.ceil(values.length/25)||1));el('ai-selected-count').textContent=values.length;el('ai-selected').innerHTML=table(['Movie','Year','IMDb','Remove'],values.slice((selectedPage-1)*25,selectedPage*25).map(m=>`<tr>${movieCells(m)}<td><button data-remove-movie="${escape(m.tconst)}" aria-label="Remove ${escape(m.primaryTitle)}">Remove</button></td></tr>`));el('ai-selected-page').textContent=`${selectedPage} / ${Math.ceil(values.length/25)||1}`;el('ai-selected-prev').disabled=selectedPage===1;el('ai-selected-next').disabled=selectedPage*25>=values.length;renderCandidates();}
 function renderCandidates(){el('ai-candidates').innerHTML=table(['Movie','Year','IMDb','Add'],candidates.map(m=>`<tr>${movieCells(m)}<td><button data-add-movie="${escape(m.tconst)}" ${selected.has(m.tconst)?'disabled':''} aria-label="Add ${escape(m.primaryTitle)}">${selected.has(m.tconst)?'Added':'Add'}</button></td></tr>`));}
 async function findMovies(){const version=++searchVersion;const r=await fetch('/api/movies?'+new URLSearchParams({q:el('ai-search').value,size:25,page:searchPage,sort:'numVotes',direction:'desc'}));const d=await r.json();if(!r.ok)throw Error(d.error);if(version!==searchVersion)return;candidates=d.rows;searchPage=d.page;searchPages=d.pages;renderCandidates();el('ai-search-page').textContent=`${searchPage} / ${searchPages} · ${d.total.toLocaleString()} matches`;el('ai-search-prev').disabled=searchPage===1;el('ai-search-next').disabled=searchPage===searchPages;}
 function addMovies(rows){for(const m of rows){if(selected.size>=10000&&!selected.has(m.tconst))throw Error('Lists support up to 10,000 movies.');selected.set(m.tconst,m);}renderSelection();}
 panel.addEventListener('click',task(async e=>{const add=e.target.closest('[data-add-movie]'),remove=e.target.closest('[data-remove-movie]'),open=e.target.closest('[data-open-run]');if(add)addMovies([candidates.find(m=>m.tconst===add.dataset.addMovie)]);if(remove){selected.delete(remove.dataset.removeMovie);renderSelection();}if(open)await openRun(Number(open.dataset.openRun));}));
 let searchTimer;el('ai-search').oninput=()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{searchPage=1;findMovies().catch(e=>status(e.message));},250);};
 el('ai-search-prev').onclick=task(async()=>{searchPage--;await findMovies();});el('ai-search-next').onclick=task(async()=>{searchPage++;await findMovies();});el('ai-add-page').onclick=task(()=>addMovies(candidates));
 el('ai-selected-prev').onclick=()=>{selectedPage--;renderSelection();};el('ai-selected-next').onclick=()=>{selectedPage++;renderSelection();};
 el('ai-add-library').onclick=task(()=>{if(typeof data==='undefined'||!data)throw Error('Open Movies and load a page first.');addMovies(data.rows);status('Added the current library page to your draft list.');});
 async function refreshLists(){const chosen=el('ai-list').value;lists=await api('lists');const options=lists.map(l=>`<option value="${l.id}">${escape(l.name)} (${l.count})</option>`).join('');el('ai-list').innerHTML='<option value="">Choose a movie list</option>'+options;el('ai-edit-list').innerHTML='<option value="">New list</option>'+options;el('ai-edit-list').value=editing||'';el('ai-list').value=chosen;}
 el('ai-edit-list').onchange=task(async()=>{if(!el('ai-edit-list').value){resetList();return;}const l=await api('lists?id='+el('ai-edit-list').value);editing=l.id;selected=new Map(l.movies.map(m=>[m.tconst,m]));el('ai-list-name').value=l.name;selectedPage=1;renderSelection();status('List loaded.');});
 function resetList(){editing=null;selected.clear();el('ai-edit-list').value='';el('ai-list-name').value='';renderSelection();}
 el('ai-new-list').onclick=resetList;
 async function saveList(copy=false){const l=await api('lists',{id:copy?null:editing,name:el('ai-list-name').value,ids:[...selected.keys()]});editing=l.id;await refreshLists();status('Movie list saved.');}
 el('ai-save-list').onclick=task(()=>saveList());el('ai-copy-list').onclick=task(()=>saveList(true));
 el('ai-archive-list').onclick=task(async()=>{if(!editing)throw Error('Choose a saved list first.');await api('archive-list',{id:editing});resetList();await refreshLists();status('List archived. Existing runs retain their snapshots.');});
 el('ai-list').onchange=()=>{const l=lists.find(l=>String(l.id)===el('ai-list').value);el('ai-count').value=l?.count||1;el('ai-count').max=l?.count||10000;preview=null;el('ai-preview').hidden=true;};
 const setup=()=>({name:el('ai-name').value,prompt:el('ai-prompt').value,list_id:Number(el('ai-list').value),count:Number(el('ai-count').value),max_tokens:Number(el('ai-tokens').value),workers:Number(el('ai-workers').value)});
 function saveDraft(){localStorage.setItem('frame-ai-prompt',JSON.stringify(setup()));}
 el('ai-save-prompt').onclick=task(()=>{saveDraft();status('Prompt draft saved in this browser.');});
 el('ai-run-form').addEventListener('input',()=>{preview=null;el('ai-preview').hidden=true;});
 el('ai-run-form').onsubmit=task(async e=>{e.preventDefault();saveDraft();const request=setup(),p=await api('preview',request);preview=request;el('ai-preview').hidden=false;el('ai-preview').innerHTML=`<h3>Ready to score ${p.movies.length} movies</h3><p>${escape(p.list_name)} · ${escape(p.model)} · ${p.workers} concurrent requests · up to ${p.max_tokens.toLocaleString()} output tokens per attempt.</p><p class="muted">Starting sends the prompt and each movie’s metadata to OpenRouter and incurs API charges. Failed requests may retry up to three times. Actual reported costs are saved. ${p.estimated_cost===null?'A dollar estimate is unavailable until there is cost history.':'Estimated cost: $'+p.estimated_cost.toFixed(5)+' based on '+p.cost_samples+' recent reported request costs. Prompt length and retries can change the total.'}</p><p>${p.movies.slice(0,5).map(m=>escape(m.primaryTitle)+' ('+escape(m.startYear??'unknown year')+')').join(', ')}${p.movies.length>5?'…':''}</p><button type="button" id="ai-start">Start scoring run</button>`;el('ai-start').onclick=task(async()=>{if(!preview)throw Error('Preview the updated settings first.');const r=await api('runs',preview);preview=null;el('ai-preview').hidden=true;await openRun(r.id);status('Run started. You can leave this tab while it scores.');});});
 async function loadHistory(){const rows=await api('runs');el('ai-history-title').textContent=page==='starred'?'Starred runs':'Runs';el('ai-history').innerHTML=table(['Run','List','Status','Progress','Failed','Created'],rows.filter(r=>page!=='starred'||r.starred).map(r=>`<tr><td><button data-open-run="${r.id}">${r.starred?'★ ':''}${escape(r.name)}</button></td><td>${escape(r.list_name)}</td><td>${escape(r.status)}</td><td>${r.completed||0} / ${r.total}</td><td>${r.failed||0}</td><td>${new Date(r.created*1000).toLocaleString()}</td></tr>`));}
 async function openRun(id){currentRun=await api('runs?id='+id);resultPage=1;show('detail');renderRun();}
 const money=n=>'$'+n.toFixed(5);
 function renderRun(){const r=currentRun;el('ai-run-title').textContent=r.name;el('ai-run-prompt').textContent=r.prompt;const done=r.items.filter(i=>i.status==='done'),failed=r.items.filter(i=>i.status==='failed'),scoring=r.items.filter(i=>i.status==='scoring'),queued=r.items.filter(i=>i.status==='queued');const attempts=r.attempts,costs=attempts.filter(a=>a.cost!==null),cost=costs.reduce((s,a)=>s+a.cost,0),seconds=attempts.reduce((s,a)=>s+a.seconds,0),tokens=attempts.reduce((s,a)=>s+(a.input_tokens||0)+(a.output_tokens||0),0),active=['running','stopping'].includes(r.status);
 const metrics={Status:r.status,Model:r.model,Progress:`${done.length} / ${r.items.length}`,Failed:failed.length,'Queued / scoring':`${queued.length} / ${scoring.length}`,Requests:attempts.length,'Reported cost':costs.length?money(cost)+(costs.length<attempts.length?' (partial)':''):'Not reported',Tokens:tokens.toLocaleString(),'Avg request time':attempts.length?(seconds/attempts.length).toFixed(1)+'s':'—','ETA':active&&attempts.length?Math.ceil((queued.length+scoring.length)*seconds/attempts.length/r.workers)+'s':'—','Average score':done.length?(done.reduce((s,i)=>s+i.score,0)/done.length).toFixed(1):'—'};
 el('ai-metrics').innerHTML=Object.entries(metrics).map(([k,v])=>`<div><span>${escape(k)}</span><strong>${escape(v)}</strong></div>`).join('');
 el('ai-run-actions').innerHTML=`<button data-run-action="star">${r.starred?'★ Unstar':'☆ Star'} run</button><button data-run-action="copy">Copy run settings</button><button data-run-action="stop" ${!active?'disabled':''}>Stop</button><button data-run-action="resume" ${active||!queued.length?'disabled':''}>Resume</button><button data-run-action="retry" ${active||!failed.length?'disabled':''}>Retry failed (${failed.length})</button><button data-run-action="archive" ${active?'disabled':''}>Archive</button>`;
 renderResults();const providers=new Map();for(const a of attempts){const k=a.provider||'Not reported',v=providers.get(k)||{count:0,tokens:0,cost:0,reported:0};v.count++;v.tokens+=(a.input_tokens||0)+(a.output_tokens||0);if(a.cost!==null){v.cost+=a.cost;v.reported++;}providers.set(k,v);}el('ai-providers').innerHTML=table(['Provider','Requests','Tokens','Reported cost'],[...providers].map(([k,v])=>`<tr><td>${escape(k)}</td><td>${v.count}</td><td>${v.tokens}</td><td>${v.reported?money(v.cost)+(v.reported<v.count?' (partial)':''):'Not reported'}</td></tr>`));}
 function resultRows(){const view=el('ai-result-view').value,q=el('ai-result-search').value.toLowerCase(),sort=el('ai-result-sort').value;return currentRun.items.filter(i=>(view==='all'||(view==='pending'?['queued','scoring'].includes(i.status):i.status===view))&&(i.movie.primaryTitle.toLowerCase().includes(q)||i.tconst.includes(q))).sort((a,b)=>sort==='title'?a.movie.primaryTitle.localeCompare(b.movie.primaryTitle):sort==='year'?(b.movie.startYear||0)-(a.movie.startYear||0):(b.score??-1)-(a.score??-1));}
 function renderResults(){if(!currentRun)return;const rows=resultRows(),done=currentRun.items.filter(i=>i.status==='done');resultPage=Math.max(1,Math.min(resultPage,Math.ceil(rows.length/25)||1));el('ai-results').innerHTML=table(['Rank','Score','Percentile','Movie','Year','Status','Response / error'],rows.slice((resultPage-1)*25,resultPage*25).map(i=>{const rank=i.score===null?'—':1+done.filter(x=>x.score>i.score).length,pct=i.score===null?'—':(100*(done.filter(x=>x.score<i.score).length+done.filter(x=>x.score===i.score).length/2)/done.length).toFixed(1);return `<tr><td>${rank}</td><td>${i.score??'—'}</td><td>${pct}</td><td>${escape(i.movie.primaryTitle)}</td><td>${i.movie.startYear??'—'}</td><td>${escape(i.status)}</td><td><details><summary>Details</summary><div class="ai-response">${escape(i.error||'')}<pre>${escape(i.response||'No response yet.')}</pre></div></details></td></tr>`;}));el('ai-result-page').textContent=`Page ${resultPage} / ${Math.ceil(rows.length/25)||1} · ${rows.length} movies`;el('ai-result-prev').disabled=resultPage===1;el('ai-result-next').disabled=resultPage*25>=rows.length;}
 el('ai-result-prev').onclick=()=>{resultPage--;renderResults();};el('ai-result-next').onclick=()=>{resultPage++;renderResults();};for(const id of ['ai-result-view','ai-result-search','ai-result-sort'])el(id).oninput=()=>{resultPage=1;renderResults();};
 el('ai-run-actions').onclick=task(async e=>{const b=e.target.closest('[data-run-action]');if(!b||b.disabled)return;const action=b.dataset.runAction;if(action==='copy'){const r=currentRun;const l=await api('lists',{name:(r.list_name+' copy').slice(0,120),ids:r.items.sort((a,b)=>a.position-b.position).map(i=>i.tconst)});await refreshLists();el('ai-list').value=l.id;el('ai-list').onchange();el('ai-name').value=(r.name+' copy').slice(0,120);el('ai-prompt').value=r.prompt;el('ai-tokens').value=r.max_tokens;el('ai-workers').value=r.workers;show('setup');status('Copied the run’s movie selection and settings. Edit the prompt and preview to start a new run.');return;}await api('action',{id:currentRun.id,action});if(action==='archive'){currentRun=null;show('runs');}else{currentRun=await api('runs?id='+currentRun.id);renderRun();}});
 el('ai-export').onclick=()=>{const csv=[['IMDb ID','Title','Year','Score','Status','Response','Error'],...resultRows().map(i=>[i.tconst,i.movie.primaryTitle,i.movie.startYear,i.score,i.status,i.response,i.error])].map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-]/,m=>"'"+m).replace(/"/g,'""')+'"').join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='movie-run-'+currentRun.id+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 let polling=false;setInterval(async()=>{if(panel.hidden||document.hidden||polling)return;polling=true;try{if(page==='detail'&&currentRun){const id=currentRun.id,updated=await api('runs?id='+id);if(page==='detail'&&currentRun?.id===id){currentRun=updated;if(!el('ai-results').querySelector('details[open]'))renderRun();}}else if(page==='runs'||page==='starred')await loadHistory();}catch(e){status(e.message);}finally{polling=false;}},3000);
 refreshLists().then(()=>{try{const d=JSON.parse(localStorage.getItem('frame-ai-prompt'));if(d){el('ai-name').value=d.name||'';el('ai-prompt').value=d.prompt||'';el('ai-list').value=d.list_id||'';el('ai-count').value=d.count||1;el('ai-tokens').value=d.max_tokens||2000;el('ai-workers').value=d.workers||4;}}catch{}renderSelection();let remembered;try{remembered=JSON.parse(localStorage.getItem('frame-ai-view'));}catch{}if(remembered?.page==='detail'&&remembered.run){openRun(remembered.run).catch(()=>show('runs'));}else show(['setup','lists','runs','starred'].includes(remembered?.page)?remembered.page:'setup');}).catch(e=>status(e.message));
})();
